import { createStore, Getters, Mutations, Actions, Module } from './src'

describe('SubModule actions and mutations access', () => {
  class FooState {
    value = 1
  }

  class FooGetters extends Getters<FooState> {
    get double(): number {
      return this.state.value * 2
    }
  }

  class FooMutations extends Mutations<FooState> {
    inc(amount: number) {
      this.state.value += amount
    }
  }

  class FooActions extends Actions<
    FooState,
    FooGetters,
    FooMutations,
    FooActions
  > {
    inc(amount: number) {
      this.commit('inc', amount)
    }
  }

  it('allows accessing submodule actions via context(store).modules.name.actions', () => {
    const foo = new Module({
      state: FooState,
      getters: FooGetters,
      mutations: FooMutations,
      actions: FooActions,
    })

    const root = new Module({
      modules: {
        foo,
      },
    })

    const store = createStore(root)
    const ctx = root.context(store)
    const fooCtx = ctx.modules.foo

    // Verify actions are accessible
    expect(fooCtx.actions).toBeDefined()
    expect(fooCtx.actions.inc).toBeDefined()
    expect(typeof fooCtx.actions.inc).toBe('function')

    // Verify actions work correctly
    return fooCtx.actions.inc(10).then(() => {
      expect(fooCtx.state.value).toBe(11)
      expect(fooCtx.getters.double).toBe(22)
    })
  })

  it('allows accessing submodule mutations via context(store).modules.name.mutations', () => {
    const foo = new Module({
      state: FooState,
      getters: FooGetters,
      mutations: FooMutations,
      actions: FooActions,
    })

    const root = new Module({
      modules: {
        foo,
      },
    })

    const store = createStore(root)
    const ctx = root.context(store)
    const fooCtx = ctx.modules.foo

    // Verify mutations are accessible
    expect(fooCtx.mutations).toBeDefined()
    expect(fooCtx.mutations.inc).toBeDefined()
    expect(typeof fooCtx.mutations.inc).toBe('function')

    // Verify mutations work correctly
    fooCtx.mutations.inc(5)
    expect(fooCtx.state.value).toBe(6)
    expect(fooCtx.getters.double).toBe(12)
  })

  it('provides the same result as direct module.context(store)', () => {
    const foo = new Module({
      state: FooState,
      getters: FooGetters,
      mutations: FooMutations,
      actions: FooActions,
    })

    const root = new Module({
      modules: {
        foo,
      },
    })

    const store = createStore(root)

    // Access via parent context
    const fooCtxViaParent = root.context(store).modules.foo

    // Access directly
    const fooCtxDirect = foo.context(store)

    // Both should have the same state
    expect(fooCtxViaParent.state.value).toBe(fooCtxDirect.state.value)

    // Both should have the same getters
    expect(fooCtxViaParent.getters.double).toBe(fooCtxDirect.getters.double)

    // Both should have accessible actions
    expect(fooCtxViaParent.actions.inc).toBeDefined()
    expect(fooCtxDirect.actions.inc).toBeDefined()

    // Both should have accessible mutations
    expect(fooCtxViaParent.mutations.inc).toBeDefined()
    expect(fooCtxDirect.mutations.inc).toBeDefined()
  })
})
EOF

